func (s LinkServiceServer) apply(ctx context.Context, ref *rove.LinkRef, doc *patchpb.Patch, by string) (*rove.Link, error) {
	plan := &ormpatch.Plan{Entity: linkOrmEntity}
	if doc != nil {
		v, err := ormpatch.Compile(linkOrmEntity, doc)
		if err != nil {
			if errors.Is(err, ormpatch.ErrUnsupported) {
				return nil, status.Errorf(codes.Unimplemented, "%s", err)
			}
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		plan = v
	}

	pred, mod, err := entpatch.Build(plan, linkPatchColumns, s.Db.Dialect())
	if err != nil {
		if errors.Is(err, entpatch.ErrValue) {
			return nil, status.Errorf(codes.InvalidArgument, "%s", err)
		}
		return nil, status.Errorf(codes.Internal, "%s", err)
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, true)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	k, err := LinkGetKey(ctx, st.Db, ref)
	if err != nil {
		return nil, err
	}
	at := &rove.LinkRef{}
	at.SetId(k[:])
	p, err := s.narrow(ctx, link.IdEQ(k))
	if err != nil {
		return nil, err
	}

	if mod == nil {
		q := st.Db.Link.Query().Where(p)
		if pred != nil {
			q.Where(predicate.Link(pred))
		}
		if ok, err := q.Exist(ctx); err != nil {
			return nil, err
		} else if !ok {
			return nil, func() error {
				if ok, err := st.Db.Link.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Link not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	} else {
		q := st.Db.Link.Update().Where(p)
		if pred != nil {
			q.Where(predicate.Link(pred))
		}
		q.Modify(mod)
		if !plan.WritesTo(13) {
			q.SetDateUpdated(st.now())
		}
		if n, err := q.Save(ctx); err != nil {
			if err, ok := err.(*ent.ConstraintError); ok {
				if sqlgraph.IsUniqueConstraintError(err) {
					return nil, status.Error(codes.AlreadyExists, "Link already exists")
				}
				if sqlgraph.IsForeignKeyConstraintError(err) {
					return nil, status.Error(codes.NotFound, "Link: referenced entity not found")
				}
			}
			return nil, err
		} else if n == 0 {
			return nil, func() error {
				if ok, err := st.Db.Link.Query().Where(p).Exist(ctx); err != nil {
					return err
				} else if !ok {
					return status.Error(codes.NotFound, "Link not found")
				}
				return status.Error(codes.FailedPrecondition, "a test in the patch did not hold")
			}()
		}
	}

	if mod != nil {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:    by,
			Key:   k,
			Patch: doc,
		}); err != nil {
			return nil, err
		}
	}

	out, err := st.Get(ctx, at.Pick())
	if err != nil {
		return nil, err
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

func (s LinkServiceServer) Erase(ctx context.Context, req *rove.LinkRef) (*rove.LinkEraseResponse, error) {
	p, err := LinkPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	if s.Rec != nil {
		v, err := st.Db.Link.Query().Where(p).OnlyId(ctx)
		if err != nil {
			if ent.IsNotFound(err) {
				return &rove.LinkEraseResponse{}, nil
			}
			return nil, err
		}

		k = v
		p = link.And(p, link.IdEQ(v))
	}

	n, err := st.Db.Link.Delete().Where(p).Exec(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:  rove.LinkService_Erase_FullMethodName,
			Key: k,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &rove.LinkEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

func LinkPick(req *rove.LinkRef) (predicate.Link, error) {
	switch req.WhichKey() {
	case rove.LinkRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return link.IdEQ(v), nil
		}
	case rove.LinkRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: Link")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}

type StewardshipServiceServer struct {
	Store

	rove.UnimplementedStewardshipServiceServer
}

// NewStewardshipServiceServer answers with a server that runs its queries with `db`.
//
// It takes the options of [Server] so that what is built here can be told
// where to report its writes and what it may see. Built without them, it
// reports nowhere and sees everything.
func NewStewardshipServiceServer(db *ent.Client, opts ...Option) rove.StewardshipServiceServer {
	s := Server{Store: Store{Db: db}}
	for _, opt := range opts {
		opt(&s)
	}
	return StewardshipServiceServer{Store: s.Store}
}

// StewardshipNarrow answers with `p` and everything else that narrows a
// read of a Stewardship, which is whatever `scope` says.
//
// Every read this package makes goes through it, and a read written by
// hand should too -- a List is the one read nothing generates, and so the
// one that would otherwise answer with rows nobody should be given.
func StewardshipNarrow(ctx context.Context, scope Scope, p predicate.Stewardship) (predicate.Stewardship, error) {
	ps := make([]predicate.Stewardship, 0, 2)
	if p != nil {
		ps = append(ps, p)
	}
	if scope != nil {
		q, err := scope.StewardshipScope(ctx)
		if err != nil {
			return nil, err
		}
		if q != nil {
			ps = append(ps, q)
		}
	}

	switch len(ps) {
	case 0:
		return nil, nil
	case 1:
		return ps[0], nil
	default:
		return stewardship.And(ps...), nil
	}
}

// narrow is [StewardshipNarrow] with this server's own scope.
func (s StewardshipServiceServer) narrow(ctx context.Context, p predicate.Stewardship) (predicate.Stewardship, error) {
	return StewardshipNarrow(ctx, s.Scope, p)
}

